'use client';

import { useState } from 'react';

export default function TriggerPriceUpdatePage() {
  const [message, setMessage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleTriggerUpdate = async () => {
    setLoading(true);
    setMessage(null);
    try {
      const res = await fetch('/api/admin/trigger-price-update', {
        method: 'POST',
      });
      if (!res.ok) {
        throw new Error(`Error: ${res.status}`);
      }
      const data = await res.json();
      setMessage(data.message || 'Price update triggered successfully!');
    } catch (err: any) {
      setMessage(`Error triggering price update: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-4">
      <h1 className="text-3xl font-bold mb-6">Manually Trigger Price Update</h1>
      <button
        onClick={handleTriggerUpdate}
        disabled={loading}
        className={`px-4 py-2 rounded text-white ${loading ? 'bg-gray-400' : 'bg-blue-500 hover:bg-blue-600'}`}
      >
        {loading ? 'Triggering...' : 'Trigger Price Update Now'}
      </button>
      {message && (
        <p className={`mt-4 ${message.startsWith('Error') ? 'text-red-500' : 'text-green-500'}`}>
          {message}
        </p>
      )}
    </div>
  );
}
